async function handleGetOrderHistory(request, env, ctx) {
  try {
    const authHeader = request.headers.get("Authorization");
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return new Response(JSON.stringify({ success: false, error: "\u672A\u6388\u6743" }), {
        status: 401,
        headers: { "Content-Type": "application/json" }
      });
    }
    const token = authHeader.substring(7);
    const db = getDB();
    const session = await db.prepare(`
      SELECT s.user_id
      FROM user_sessions s
      WHERE s.token = ? AND s.expires_at > datetime('now')
    `).bind(token).first();
    if (!session) {
      return new Response(JSON.stringify({ success: false, error: "\u4F1A\u8BDD\u5DF2\u8FC7\u671F" }), {
        status: 401,
        headers: { "Content-Type": "application/json" }
      });
    }
    const ordersResult = await db.prepare(`
      SELECT o.*, c.max_ips
      FROM user_orders o
      LEFT JOIN codes c ON o.code = c.code
      WHERE o.user_id = ?
      ORDER BY o.created_at DESC
      LIMIT 50
    `).bind(session.user_id).all();
    const orders = ordersResult.results || [];
    return new Response(JSON.stringify({
      success: true,
      orders
    }), {
      headers: { "Content-Type": "application/json" }
    });
  } catch (error) {
    console.error("\u83B7\u53D6\u8BA2\u5355\u5386\u53F2\u5931\u8D25:", error);
    return new Response(JSON.stringify({ success: false, error: "\u670D\u52A1\u5668\u9519\u8BEF" }), {
      status: 500,
      headers: { "Content-Type": "application/json" }
    });
  }
}
